  'We received your receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Recebemos seu recibo, obrigado 🌱 Entraremos em contato sobre seu pagamento o mais breve possível.',
  'We received your receipt, thank you 🌱 Your donation is confirmed.' => 'Recebemos seu recibo, obrigado 🌱 Sua doação está confirmada.',
  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Já havíamos recebido este recibo, obrigado 🌱 Entraremos em contato sobre seu pagamento o mais breve possível.',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => 'Este recibo parece ter sido carregado em nosso sistema antes. O mesmo recibo não poderá ser utilizado para uma segunda doação. Se você fez um pagamento diferente, envie esse recibo; nossa equipe também irá verificar.',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => 'Recebemos seu recibo. O valor nele (%1$s) parece não corresponder ao valor da sua doação (%2$s). Você poderia verificar? Se você fez um pagamento diferente, pode escrever aqui; nossa equipe também dará uma olhada.',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => 'Recebemos o seu recibo, mas o destinatário não parece ser a nossa associação. As doações são feitas somente para nossa conta em nome de "%s". Você poderia verificar? Nossa equipe também irá dar uma olhada.',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => 'Recebemos seu recibo, mas o destinatário não parece corresponder à nossa conta. Você poderia verificar? Nossa equipe também irá dar uma olhada.',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => 'O arquivo que você enviou não se parece com um recibo de pagamento. Se você pagou, pode enviar o recibo ou uma captura de tela da tela de pagamento aqui.',
