  '+ New report' => '+ Novo relatório',
  'The recipient\'s number comes from Users › Profile › WhatsApp number; permissions from Users › Roles and access (receive reports, view overall report, manage reports). Reports go out at the chosen time; without a server scheduler they are sent on the next site visit or chat panel use.' => 'O número do destinatário vem de Usuários › Perfil › Número do WhatsApp; permissões de Usuários › Funções e acesso (receber relatórios, visualizar relatório geral, gerenciar relatórios). Os relatórios saem no horário escolhido; sem um agendador de servidor, eles são enviados na próxima visita ao site ou uso do painel de chat.',
  'Invalid phone number.' => 'Número de telefone inválido.',
  'First add a WhatsApp connection under Settings › Connections.' => 'Primeiro adicione uma conexão do WhatsApp em Configurações › Conexões.',
