  'Reply text cannot be empty.' => 'O texto de resposta não pode ficar vazio.',
  'Connection not found. Save the settings first.' => 'Conexão não encontrada. Salve as configurações primeiro.',
  'The message was only image code; it was not sent.' => 'A mensagem era apenas um código de imagem; não foi enviado.',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => 'Este contato está na lista de bloqueio; nenhuma mensagem é enviada. Remova-os da lista de bloqueio para escrever novamente.',
  'Message could not be saved.' => 'A mensagem não pôde ser salva.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Este contato escreve de um número oculto do WhatsApp (@lid) e a API Evolution (versão%s) não conseguiu enviar para este endereço. Atualize o servidor Evolution API para 2.3 ou posterior; se chegar o número real do contato, o plugin envia para lá.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Este contato escreve de um número oculto do WhatsApp (@lid) e a Evolution API não conseguiu enviar para este endereço. Atualize o servidor Evolution API para 2.3 ou posterior; se chegar o número real do contato, o plugin envia para lá.',
  'No WhatsApp connection.' => 'Sem conexão com WhatsApp.',
  'Connected ✓' => 'Conectado ✓',
  'Not connected (state: %s). Connect with QR.' => 'Não conectado (estado:%s). Conecte-se com QR.',
  'Webhook points to this site ✓' => 'Webhook aponta para este site ✓',
  'Evolution API version: %s' => 'Versão da API de evolução:%s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(antigo: respostas a contatos com números ocultos (@lid) podem falhar, atualize para 2.3 ou posterior)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'O webhook não está apontado para este site. Pressione "Configurar webhook".',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Configuração do Webhook ✓ As mensagens recebidas agora chegarão aqui.',
  'Importing recent chats, this may take a while…' => 'Importando bate-papos recentes, isso pode demorar um pouco...',
  'Messages stored in Evolution: %s' => 'Mensagens armazenadas no Evolution:%s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'O Evolution não armazena mensagens, portanto mensagens mais antigas não podem ser carregadas. No servidor Evolution, configure DATABASE_SAVE_DATA_NEW_MESSAGE e DATABASE_SAVE_DATA_HISTORIC como true; para conversas mais antigas, mantenha "Sincronizar histórico completo" ativado nas configurações da instância ao reconectar a linha com QR.',
  '%1$s chats, %2$s messages imported ✓' => 'Bate-papos%1$s, mensagens%2$simportadas ✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'Leia este código via WhatsApp › Dispositivos vinculados › Vincule um dispositivo.',
  'Pairing code:' => 'Código de emparelhamento:',
  'This line is already connected ✓' => 'Esta linha já está conectada ✓',
  'Save the settings first.' => 'Salve as configurações primeiro.',
  'Error:' => 'Erro:',
  'Delete this connection? Chat history is kept.' => 'Excluir esta conexão? O histórico do bate-papo é mantido.',
  'Asking the AI…' => 'Perguntando à IA...',
  'Working ✓ (%2$s ms): %1$s' => 'Trabalhando ✓ (%2$sms):%1$s',
  'Save the key and model first.' => 'Salve a chave e o modelo primeiro.',
  'Connections' => 'Conexões',
  'Auto replies' => 'Respostas automáticas',
  'AI and assistant' => 'IA e assistente',
  'System check' => 'Verificação do sistema',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'Conecte sua linha do WhatsApp, gerencie respostas automáticas e rótulos.',
  'Open chats' => 'Bate-papos abertos',
  'Settings saved.' => 'Configurações salvas.',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'Conexões e configurações que o call center precisa. O status salvo é mostrado; use os botões "teste" em cada guia para uma verificação ao vivo. As mesmas verificações também aparecem com os outros plugins na tela de verificação do sistema do tema.',
  'WhatsApp lines' => 'Linhas do WhatsApp',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'As mensagens são enviadas e recebidas através da API Evolution. As conexões do WhatsApp são gerenciadas no Flux Mail; escolha qual usar aqui. A URL e a chave de API permanecem lá, então você não precisa atualizá-las aqui quando elas mudarem.',
  'Communication › Connections' => 'Comunicação › Conexões',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'As mensagens são enviadas e recebidas via Evolution API. Se um provedor Evolution estiver configurado em Flux Certificates, você poderá escolher a mesma conexão; o URL e a chave da API permanecem lá.',
  'Add line' => 'Adicionar linha',
  'Setup steps' => 'Etapas de configuração',
  'Add the line and save.' => 'Adicione a linha e salve.',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => 'Use "Testar conexão" para ver se o Evolution está acessível. Se a linha não estiver vinculada, escolha “Conectar com QR” e escaneie-a no telefone.',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => 'Pressione "Configurar webhook". Mensagens recebidas e mensagens enviadas do telefone e dos Certificados Flux aparecem aqui ao vivo.',
  'Optionally bring in past messages with "Import recent chats".' => 'Opcionalmente, traga mensagens anteriores com "Importar bate-papos recentes".',
  'connected' => 'conectado',
  'connecting' => 'conectando',
  'not connected' => 'não conectado',
  'not on server' => 'não no servidor',
  'unreachable' => 'inacessível',
  'Flux Mail connection: %s' => 'Conexão Flux Mail:%s',
  'Flux Mail connection #%d (not found or disabled)' => 'Conexão Flux Mail #%d(não encontrada ou desativada)',
  'Use Flux Certificates provider: %s' => 'Use o provedor de certificados Flux:%s',
  'Enter separate Evolution API details' => 'Insira detalhes separados da API Evolution',
  'Line name (e.g. Main line)' => 'Nome da linha (por exemplo, linha principal)',
  'Connection details' => 'Detalhes de conexão',
  'API URL' => 'URL da API',
  'Instance name' => 'Nome da instância',
  'API key (apikey)' => 'Chave de API (apikey)',
  '•••••••• (saved; type to change)' => '•••••••• (salvo; digite para alterar)',
  'Webhook URL' => 'URL do webhook',
  'Regenerate secret key' => 'Regenerar chave secreta',
  'Last webhook: %s' => 'Último webhook:%s',
  'No webhook received yet.' => 'Nenhum webhook recebido ainda.',
  'Test connection' => 'Conexão de teste',
  'Connect with QR' => 'Conecte-se com QR',
  'QR, status and accounts: Communication › Connections' => 'QR, status e contas: Comunicação › Conexões',
  'Set up webhook' => 'Configurar webhook',
  'Import recent chats' => 'Importe bate-papos recentes',
  'The webhook URL and test buttons appear after saving.' => 'O URL do webhook e os botões de teste aparecem após salvar.',
  'Appearance' => 'Aparência',
  'Panel title' => 'Título do painel',
  'Site name if empty. The {brand} variable uses this too.' => 'Nome do site se estiver vazio. A variável{brand}também usa isso.',
  'Accent color' => 'Cor de destaque',
  'Behavior' => 'Comportamento',
  'Send read receipts (blue ticks) when a chat is opened' => 'Envie recibos de leitura (marcas azuis) quando um bate-papo for aberto',
  'Prefix messages with the agent\'s name (*Name:*)' => 'Prefixar mensagens com o nome do agente (*Nome:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'Os agentes veem apenas os chats atribuídos a eles e os chats não atribuídos (os administradores veem todos)',
  'Also show WhatsApp group messages' => 'Mostrar também mensagens de grupo do WhatsApp',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => 'Nova interface (experimental): a página Chats abre com a mesma tela do desktop e do aplicativo móvel',
  'Live update interval (sec)' => 'Intervalo de atualização ao vivo (seg)',
  'The open tab checks for new messages at this interval (10 recommended). In a background tab it checks once a minute, and less often after errors.' => 'A aba aberta verifica novas mensagens neste intervalo (10 recomendado). Em uma guia em segundo plano, ele verifica uma vez por minuto e com menos frequência após erros.',
  'Agents' => 'Agentes',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'Dê a um usuário a função%s; eles veem apenas a tela de bate-papo e não podem abrir as configurações. Os administradores sempre têm acesso.',
  'Add new user' => 'Adicionar novo usuário',
  'Data' => 'Dados',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'Exclua também todos os bate-papos, mensagens e arquivos de mídia quando o plugin for excluído',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'Os arquivos de mídia são mantidos em wp-content/uploads/flx-chat, fechados ao acesso externo. Eles se movem com os uploads quando o site é migrado.',
  'Mon' => 'segunda-feira',
  'Tue' => 'Terça',
  'Wed' => 'Quarta',
  'Thu' => 'Qui',
  'Fri' => 'Sexta-feira',
  'Sat' => 'Sábado',
  'Sun' => 'Sol',
  'Welcome message' => 'Mensagem de boas-vindas',
  'Send automatically to people who write to us for the first time' => 'Envie automaticamente para pessoas que nos escrevem pela primeira vez',
  'Away message' => 'Mensagem de ausência',
  'Auto reply to messages received outside business hours' => 'Resposta automática a mensagens recebidas fora do horário comercial',
  'Business days' => 'Dias úteis',
  'Start' => 'Começar',
  'End' => 'Fim',
  'At most once per contact every (hours)' => 'No máximo uma vez por contato a cada (horas)',
  'Timezone: %1$s. Now: %2$s.' => 'Fuso horário:%1$s. Agora:%2$s.',
  'within business hours' => 'dentro do horário comercial',
  'outside business hours' => 'fora do horário comercial',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => 'As variáveis{first_name},{name},{brand},{site},{date}podem ser utilizadas nos textos.',
  'Chat labels' => 'Marcadores de bate-papo',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'Rotule os bate-papos e filtre a lista (por exemplo, Doação, Reclamação, Acompanhamento).',
  'Add label' => 'Adicionar rótulo',
  'Label name' => 'Nome da etiqueta',
  'Creating records from chats' => 'Criando registros de bate-papos',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'Os botões no cabeçalho do bate-papo criam um registro de doação (Flux Donate) e um certificado (Flux Certificates), e um recibo recebido é combinado com um registro. Se um plugin não estiver instalado, seu botão ficará oculto.',
  'Agents can create donation records and match receipts' => 'Os agentes podem criar registros de doações e combinar recibos',
  'Agents can create and send certificates' => 'Os agentes podem criar e enviar certificados',
  'Show quick reply bubbles above the message box' => 'Mostrar balões de resposta rápida acima da caixa de mensagem',
  'Donation messages' => 'Mensagens de doação',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'Textos prontos enviados para a pessoa quando um registro é criado (editáveis antes do envio). Se deixado em branco, o texto padrão será usado.',
  'Awaiting payment (promised transfer)' => 'Aguardando pagamento (transferência prometida)',
  'Donation received' => 'Doação recebida',
  'Receipt confirmed' => 'Recibo confirmado',
  'Bank details ({bank})' => 'Dados bancários ({bank})',
  'Recipient name, bank, IBAN' => 'Nome do destinatário, banco, IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => 'Se estiver vazio, a conta em WooCommerce › Pagamentos › Transferência bancária será usada.',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variáveis:{first_name},{name},{donation},{amount},{quantity},{bank},{certificate_link},{agent},{brand},{date}.',
  'AI connection' => 'Conexão de IA',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'Chaves, cache de prompt, limites de gastos e registros de uso vêm do plugin Flux AI & MCP; todas as solicitações de IA do Call Center passam por ele. As opções de modelo ficam aqui; se um campo estiver vazio, será utilizado o modelo escolhido para este plugin no Flux AI (ou o padrão).',
  'Open Flux AI settings' => 'Abra as configurações do Flux AI',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'AI precisa do plugin Flux AI & MCP. Instale e ative-o e, em seguida, insira a chave OpenRouter e/ou Anthropic em Flux AI & MCP › Configurações. Até então sugestões, assistente, leitura de recibos, mensagens de voz e resumos estão desativados.',
  'Creativity (0–1)' => 'Criatividade (0–1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => 'Valores mais baixos fornecem respostas mais consistentes, valores mais altos, respostas mais livres. 0,4 recomendado.',
  'Model (for suggestions)' => 'Modelo (para sugestões)',
  'Assistant model (optional)' => 'Modelo assistente (opcional)',
  'Model above' => 'Modelo acima',
  'Only models that support tools are listed.' => 'Somente modelos que suportam ferramentas estão listados.',
  'Receipt reading model (optional)' => 'Modelo de leitura de recibo (opcional)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => 'Se o modelo selecionado não conseguir ler imagens, um modelo de visão barato será usado automaticamente.',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => 'Este mês (%1$s): solicitações%2$s, tokens%3$s, cerca de $%4$s.',
  'Reply suggestions' => 'Sugestões de resposta',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'Acima da caixa de mensagem, é sugerida a próxima mensagem da conversa. O agente clica em “Enviar” ou leva para a caixa com “Editar”. Uma sugestão nunca é enviada sozinha.',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => 'Prepare uma sugestão automaticamente quando chegar a última mensagem da pessoa (se estiver desativada, pergunte com o botão ✨)',
  'Organization info and tone' => 'Informações e tom da organização',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => 'Por exemplo Nossa associação planta mudas em Istambul. O plantio é feito todos os anos entre novembro e março. O certificado é enviado no WhatsApp após a doação. Use um tom caloroso, mas formal.',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => 'Sugestões e o assistente usam isso. Tipos de doações, preços, dados bancários e respostas rápidas são adicionados automaticamente.',
  'Suggestion provider' => 'Provedor de sugestões',
  'Donation assistant (automatic replies)' => 'Assistente de doações (respostas automáticas)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'Quando ativado, o assistente responde sozinho: cumprimenta, pergunta o nome para endereçá-los, envia opções de doações e preços, opcionalmente coleta e-mail e “em nome de quem”, e pede confirmação após cada alteração. Após a confirmação abre um registro “aguardando pagamento” no Flux Donate e envia o link da doação, destinatário, IBAN e referência em mensagens separadas. Se o tópico deixar doações, ele passa o chat para a equipe.',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'O plugin Flux Donate não está ativo; o assistente não pode criar registros de doações.',
  'Instructions, documents, AI chats and test chat' => 'Instruções, documentos, chats de IA e chat de teste',
  'Turn on the donation assistant (untick to turn it off everywhere)' => 'Ative o assistente de doações (desmarque para desligá-lo em todos os lugares)',
  'Which chats should it reply to' => 'A quais bate-papos ele deve responder',
  'In all chats (recommended)' => 'Em todos os chats (recomendado)',
  'In chats not assigned to an agent' => 'Em chats não atribuídos a um agente',
  'Only outside working hours' => 'Somente fora do horário de trabalho',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'Quando um agente escreve em um chat (do painel ou do telefone), o assistente fica quieto ali pelo tempo abaixo. Use o botão do assistente no cabeçalho do chat para ativá-lo ou desativá-lo por chat.',
  'Test mode: reply only to the numbers below' => 'Modo teste: responda apenas aos números abaixo',
  'Test numbers' => 'Números de teste',
  'Separate with commas or new lines. Not used when test mode is off.' => 'Separe com vírgulas ou novas linhas. Não usado quando o modo de teste está desativado.',
  'Quiet after an agent writes (hours)' => 'Silêncio depois que um agente escreve (horas)',
  'Quantities in the price list' => 'Quantidades na tabela de preços',
  'Conversation history (hours)' => 'Histórico de conversas (horas)',
  'Before replying, the assistant reads all messages from this period.' => 'Antes de responder, o assistente lê todas as mensagens deste período.',
  'Donation types the assistant offers' => 'Tipos de doação que o assistente oferece',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => 'Se nenhum for selecionado, todos os tipos abertos serão oferecidos. Quando um novo tipo é aberto no Flux Donate, o assistente também sabe disso.',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => 'Pré-verificação de recebimento: quando o contato envia um recibo, a IA compara o valor, destinatário e IBAN com a doação, informa o resultado ao contato, anexa o arquivo ao registro da doação e entrega o chat para a equipe para aprovação final (não marca como pago)',
  'Last line of the price list' => 'Última linha da lista de preços',
  'Payment details' => 'Detalhes de pagamento',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => 'Se o destinatário e o IBAN estiverem vazios, serão usados aqueles em WooCommerce › Pagamentos › Transferência bancária (a conta mostrada nos pedidos). Preencha-os apenas se o assistente usar uma conta diferente.',
  'Recipient name' => 'Nome do destinatário',
  'Transfer description' => 'Descrição da transferência',
  'Variables: {type}, {name}, {amount}, {quantity}' => 'Variáveis:{type},{name},{amount},{quantity}',
  'Donation page URL' => 'URL da página de doação',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => 'O tipo e a quantidade selecionados são adicionados ao link (?flxb_opt=...&flxb_qty=...).',
  'Message after the payment details' => 'Mensagem após os detalhes do pagamento',
  'Donation cancellation question' => 'Pergunta sobre cancelamento de doação',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'O assistente cancela apenas as doações não pagas, com a confirmação da pessoa. Vazio = texto padrão. Variáveis:{bagis},{tutar}.',
  'Message sent when the daily limit is reached' => 'Mensagem enviada quando o limite diário é atingido',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'Enviado uma vez quando um chat atinge o limite de respostas do dia; o chat é entregue à equipe. Redefina-o no menu ⋮ › Uso do assistente do bate-papo.',
  'Message sent when handing over to the team' => 'Mensagem enviada ao entregar para a equipe',
  'Message sent when the assistant cannot answer' => 'Mensagem enviada quando o assistente não consegue atender',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'Caso a IA falhe, o tempo limite seja atingido ou a fila fique muito longa, essa mensagem é enviada e o chat é repassado para a equipe; a pessoa nunca fica sem resposta.',
  'Minimum wait before the holding message (s)' => 'Espera mínima antes da(s) mensagem(s) de retenção',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => 'A mensagem em espera não é enviada até alguns segundos após a mensagem da pessoa; enquanto isso, o assistente tenta novamente.',
  'Longest time for one answer (s)' => 'Maior tempo para uma(s) resposta(s)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'A Hostinger pode cortar solicitações em aproximadamente 60 segundos; 50 é recomendado.',
  'Numbers notified on handoff' => 'Números notificados na transferência',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'Quando o assistente entrega um chat para a equipe, uma mensagem de WhatsApp é enviada para esses números da mesma linha: nome do contato, telefone, motivo, últimas mensagens e link do painel. Separe com vírgulas ou novas linhas. O assistente não fala com esses números.',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => 'Quando o contato escreve uma dessas, o assistente envia imediatamente a mensagem de hand-off acima e desliga naquele chat. Se deixado em branco, a lista de exemplos será usada.',
  'Extra instructions for the assistant' => 'Instruções extras para o assistente',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => 'Por exemplo As mudas são plantadas em Kocaeli. Os certificados são enviados assim que a doação for confirmada.',
  'Last message when a contact opts out' => 'Última mensagem quando um contato desativa',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => 'Se alguém escrever algo como “não me mande uma mensagem”, o assistente enviará essa mensagem e a colocará na lista de bloqueio. Uma pessoa na lista de bloqueio não recebe WhatsApp, e-mail ou SMS; gerencie a lista em Bate-papos › ☰ › Lista de bloqueio.',
  'Contact memory and background jobs' => 'Memória de contato e trabalhos em segundo plano',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => 'Memória de contato: o assistente lembra detalhes duradouros (forma de endereço, nomes de parentes, números, preferências); bate-papos expirados são resumidos',
  'Summarize a chat after it has been quiet for (hours)' => 'Resuma um bate-papo depois que ele estiver silencioso por (horas)',
  'Maximum jobs at the same time' => 'Máximo de trabalhos ao mesmo tempo',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => 'Quantas pessoas podem ser atendidas ao mesmo tempo. As respostas do assistente sempre vêm em primeiro lugar; os resumos não começam enquanto alguém está sendo atendido ou esperando. Cada trabalho usa um trabalhador PHP: em hospedagem compartilhada, fique abaixo da metade do limite total de trabalhadores dos seus sites (por exemplo, 20-30 de 60 trabalhadores).',
  'Workers reserved for replies' => 'Trabalhadores reservados para respostas',
  'This many workers never take summaries or reminders.' => 'Muitos trabalhadores nunca aceitam resumos ou lembretes.',
  'Summary hours' => 'Horário de resumo',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => 'Os resumos são executados apenas entre esses horários (exceto um manual "Resumir agora"). Se ambos forem iguais, a qualquer momento.',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => 'Quando alguém envia uma mensagem de voz, o assistente transforma em texto e responde (o texto também aparece no painel como uma linha do sistema)',
  'Longest voice message (sec)' => 'Mensagem de voz mais longa (seg)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => 'Para mensagens mais longas, o assistente diz “a mensagem de voz era muito longa para ouvirmos”.',
  'Voice message model (optional)' => 'Modelo de mensagem de voz (opcional)',
  'Cheap audio model (Gemini Flash Lite)' => 'Modelo de áudio barato (Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'Deve ser um modelo OpenRouter que aceite áudio (Claude não). É necessária uma chave OpenRouter.',
  'Images' => 'Imagens',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'Deixe o assistente desenhar uma imagem quando for útil (tabela, relatório, diagrama); vai para o WhatsApp como imagem, o texto é enviado separadamente',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'O renderizador de imagem Flux AI é usado (Flux AI & MCP › Configurações › Imagens).',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'Nenhum renderizador de imagem no servidor: insira um endereço Gotenberg em Flux AI & MCP › Configurações › Imagens ou instale o Imagick (SVG). Até então o assistente não desenha imagens.',
  'Works once Flux AI 0.2.0 or later is installed.' => 'Funciona quando o Flux AI 0.2.0 ou posterior estiver instalado.',
  'Donation on behalf of someone' => 'Doação em nome de alguém',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => 'Caso a doação esteja em nome de outra pessoa e tenha sido informado o número dela (cartão de contato ou número digitado), envie também o certificado para esse número no WhatsApp assim que o pagamento for aprovado',
  'Message sent before the certificate' => 'Mensagem enviada antes do certificado',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => 'Em seguida, a mensagem do certificado WhatsApp da Flux Certificates é enviada. Variáveis:{ad},{bagisci},{bagis},{brand}.',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => 'Caso uma pessoa pergunte, o assistente configura um lembrete (por exemplo, “lembre-me do plantio de mudas todo mês”, “envie-me seus projetos mais recentes todo mês”, “peça-me uma muda todo mês”); na hora certa, o assistente escreve e envia a mensagem',
  'When no time is given' => 'Quando nenhum tempo é dado',
  'At most per person' => 'No máximo por pessoa',
  'Staff (Flux Roles)' => 'Equipe (funções de fluxo)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'Funciona assim que o Flux Roles 1.1.0 estiver instalado: usuários cujo número está definido em Perfil › Número do WhatsApp obtêm ferramentas assistentes extras com base em suas permissões.',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => 'Conceder ferramentas auxiliares extras aos números da equipe com permissão (doação em nome de alguém com link de pagamento, meus doadores, relatório geral)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => 'Notificar a equipe no WhatsApp quando uma doação indicada for paga ou cancelada',
  'First message to the donor for a donation opened by staff' => 'Primeira mensagem ao doador para uma doação aberta pela equipe',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'Olá{ad}🌱 Sua solicitação de doação{bagis}via{personel}foi recebida. Você pode pagar com os detalhes abaixo.',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Segue link de pagamento e dados bancários. Variáveis:{ad},{adsoyad},{personel},{bagis}.',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'Quando uma doação indicada por um funcionário for paga e seus certificados forem feitos, envie-os também para o funcionário no WhatsApp (assim como o doador)',
  'Message sent to the staff member before the certificate' => 'Mensagem enviada ao funcionário antes do certificado',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variáveis:{ad},{bagisci},{bagis},{no},{brand}.',
  'How many times staff can resend a donation\'s certificate' => 'Quantas vezes a equipe pode reenviar um certificado de doação',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'O assistente lista os destinatários e pede confirmação antes de enviar. 0: desligado.',
  'Code verification for record lookups' => 'Verificação de código para pesquisas de registros',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => 'Quando uma pessoa solicitar seu cadastro e seu número estiver oculto (ou doar com outro número/e-mail), envie um código para o número ou e-mail que ela fornecer; uma vez verificado, seus registros também são mostrados',
  'Code validity (min)' => 'Validade do código (min)',
  'Maximum failed attempts' => 'Máximo de tentativas falhadas',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => 'Códigos que não puderam ser enviados, códigos errados e códigos expirados contam. No limite a pessoa recebe a mensagem abaixo e a equipe é avisada; o assistente continua respondendo outras perguntas, mas não compartilha detalhes do registro por 24 horas.',
  'Code to phone' => 'Código para telefone',
  'WhatsApp, SMS if it fails' => 'WhatsApp, SMS se falhar',
  'WhatsApp only' => 'Apenas WhatsApp',
  'SMS only' => 'Somente SMS',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => 'SMS é usado se o Flux Mail tiver uma conexão SMS (por exemplo, Netgsm).',
  'Message when verification fails' => 'Mensagem quando a verificação falha',
  'WhatsApp/SMS code message' => 'Mensagem de código WhatsApp/SMS',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => 'Texto padrão se estiver vazio. Variáveis:{kod},{dk},{marka}. O texto do e-mail é editado em Flux Mail › Modelos de e-mail.',
  'Site content' => 'Conteúdo do site',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'Deixe o assistente pesquisar o conteúdo publicado do site (por exemplo, "você tem uma postagem sobre plantio de árvores")',
  'Content types to search' => 'Tipos de conteúdo para pesquisar',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'Somente conteúdo publicado sem senha é retornado. Rascunhos, conteúdo privado e protegido por senha nunca são mostrados.',
  'Categories and tags never to share' => 'Categorias e tags para nunca compartilhar',
  'e.g. corporate-offers, internal-notice' => 'por exemplo ofertas corporativas, aviso interno',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => 'Nome ou slug, separados por vírgula. Para ocultar um único item, marque “Não permitir que o assistente compartilhe este conteúdo” na tela de edição.',
