  'Success is attributed to the assistant model. Runs before 1.6.3 did not separate assistant and judge, so they show as "Assistant + judge".' => 'O sucesso é atribuído ao modelo assistente. As corridas anteriores a 1.6.3 não separavam assistente e juiz, então elas aparecem como "Assistente + juiz".',
