  'assistant {a} + judge {j}' => 'assistente{a}+ juiz{j}',
  'Based on average token usage of {n} past scenario results; actual cost per scenario may vary.' => 'Com base no uso médio de token dos resultados do cenário anterior{n}; o custo real por cenário pode variar.',
  'No runs yet; default estimate: ~{i} input / {o} output tokens per donor message.' => 'Nenhuma corrida ainda; estimativa padrão: ~ tokens de entrada{i}/saída{o}por mensagem do doador.',
