  '{tur}, {birim} and {brand} can be used. If there are only customer messages, the assistant replies to each in turn. If you add assistant messages it becomes a continuation scenario: the written history is given as-is and the assistant replies only to the last customer message.' => '{tur},{birim}e{brand}podem ser usados. Se houver apenas mensagens de clientes, o assistente responde a cada uma delas. Se você adicionar mensagens do assistente, torna-se um cenário de continuação: o histórico escrito é fornecido como está e o assistente responde apenas à última mensagem do cliente.',
  'E.g. payment_info, cancel_donation, receipt_check. Tools disabled on this site are not checked.' => 'Por exemplo info_pagamento, cancelar_doação, recibo_cheque. As ferramentas desativadas neste site não são verificadas.',
  'Who is writing?' => 'Quem está escrevendo?',
  'Starting state (test)' => 'Estado inicial (teste)',
  'The scenario runs isolated like the test chat; what you select here exists only in this test. In a customer message, {kod} becomes the verification code from the test panel.' => 'O cenário é executado isolado como o chat de teste; o que você seleciona aqui existe apenas neste teste. Numa mensagem do cliente,{kod}torna-se o código de verificação do painel de teste.',
  'End state' => 'Estado final',
  'When the conversation ends, the test state is checked (was a donation opened, canceled, a code sent…). Tools disabled on this site are not checked.' => 'Quando a conversa termina, o estado do teste é verificado (uma doação foi aberta, cancelada, um código enviado...). As ferramentas desativadas neste site não são verificadas.',
