  'Cannot write to uploads/flx-chat; incoming photos, voice notes and documents cannot be saved. Check folder permissions.' => 'Não é possível gravar em uploads/flx-chat; fotos recebidas, notas de voz e documentos não podem ser salvos. Verifique as permissões da pasta.',
