  'Using Flux Mail connection: %s.' => 'Usando conexão Flux Mail:%s.',
  'Still using the old provider in Flux Certificates; move the connection to Flux Mail and select it here.' => 'Ainda utilizando o antigo provedor em Certificados Flux; mova a conexão para Flux Mail e selecione-a aqui.',
