  'API URL, key and instance are entered in this plugin.' => 'URL da API, chave e instância são inseridas neste plugin.',
  '%s: line status' => '%s: status da linha',
  'Phone connected (last seen %s).' => 'Telefone conectado (visto pela última vez%s).',
