  'Phone not connected (state: %1$s, %2$s). Reconnect with "Connect with QR".' => 'Telefone não conectado (estado:%1$s,%2$s). Reconecte com "Conectar com QR".',
  '%s: Evolution API version' => '%s: versão da API de evolução',
  'Evolution API %s is in use. Replies to hidden-number (@lid) contacts may fail; update the server to 2.3 or later.' => 'A API de evolução%sestá em uso. As respostas a contatos com números ocultos (@lid) podem falhar; atualize o servidor para 2.3 ou posterior.',
  '%s: webhook (incoming messages)' => '%s: webhook (mensagens recebidas)',
  'No events have arrived from Evolution; incoming messages will not show in the panel. Press "Set up webhook".' => 'Nenhum evento chegou da Evolution; as mensagens recebidas não serão exibidas no painel. Pressione "Configurar webhook".',
  'Last event arrived %s. The line may just be quiet; send yourself a message or set up the webhook again to be sure.' => 'O último evento chegou%s. A linha pode estar silenciosa; envie uma mensagem para si mesmo ou configure o webhook novamente para ter certeza.',
  'Last event arrived %s.' => 'O último evento chegou%s.',
  'Flux Mail integration' => 'Integração Flux Mail',
  'Active: WhatsApp connections are taken from Communication › Connections.' => 'Ativo: as conexões do WhatsApp são obtidas em Comunicação › Conexões.',
  'Flux Mail is not active; connections are taken from Flux Certificates or from this plugin.' => 'Flux Mail não está ativo; as conexões são obtidas dos Certificados Flux ou deste plugin.',
  'Flux Certificates integration' => 'Integração de certificados Flux',
  'Active: certificates can be created and sent from chats.' => 'Ativo: certificados podem ser criados e enviados a partir de chats.',
  'Flux Certificates is not active; certificate actions in chats are off.' => 'Os Certificados Flux não estão ativos; as ações de certificado em bate-papos estão desativadas.',
  'Flux Donate integration' => 'Integração Flux Donate',
  'Active: donation records, receipt matching and the assistant are available from chats.' => 'Ativo: registros de doações, correspondência de recibos e assistente estão disponíveis nos chats.',
  'Flux Donate is not active; donation records, receipt matching and the donation assistant are off.' => 'Flux Donate não está ativo; registros de doações, correspondência de recibos e assistente de doações estão desativados.',
  'The Flux AI & MCP plugin is not installed; AI features (suggestions, assistant, receipt reading, voice messages, summaries) are off. Install Flux AI and enter the key there.' => 'O plugin Flux AI & MCP não está instalado; Os recursos de IA (sugestões, assistente, leitura de recibos, mensagens de voz, resumos) estão desativados. Instale o Flux AI e insira a chave lá.',
  'No key has been entered in Flux AI; message suggestions and the assistant are off.' => 'Nenhuma chave foi inserida no Flux AI; sugestões de mensagens e o assistente estão desligados.',
  'Key saved but no model selected.' => 'Chave salva, mas nenhum modelo selecionado.',
  'No provider key has been entered in Flux AI for the selected model (%s).' => 'Nenhuma chave de provedor foi inserida no Flux AI para o modelo selecionado (%s).',
  'Key saved, model: %s. Use "Test connection" for a live check.' => 'Chave salva, modelo:%s. Use "Conexão de teste" para uma verificação ao vivo.',
  'Donation assistant' => 'Assistente de doações',
  'Off.' => 'Desligado.',
  'AI key or model is missing.' => 'A chave ou modelo AI está faltando.',
  'On but not replying: ' => 'Ligado, mas sem responder:',
  'On. Donation types offered: %s.' => 'Ligado. Tipos de doação oferecidos:%s.',
  '%s does not support tools; choose a tool-capable model for the assistant.' => '%snão oferece suporte a ferramentas; escolha um modelo compatível com ferramentas para o assistente.',
  'Receipt reading model' => 'Modelo de leitura de recibo',
  '%s cannot read images; the receipt pre-check will not work. Choose an image-capable receipt reading model.' => '%snão consegue ler imagens; a pré-verificação do recibo não funcionará. Escolha um modelo de leitura de recibos com capacidade de imagem.',
  'Assistant payment details' => 'Detalhes de pagamento do assistente',
  'Recipient name and IBAN set.' => 'Nome do destinatário e conjunto de IBAN.',
  'Recipient name or IBAN missing; bank details cannot be sent after confirmation.' => 'Nome do destinatário ou IBAN ausente; os dados bancários não podem ser enviados após a confirmação.',
  'Donation page link' => 'Link da página de doações',
  'Donation page not found; the assistant will not send a link.' => 'Página de doação não encontrada; o assistente não enviará um link.',
  'Background requests' => 'Solicitações em segundo plano',
  'The site could not send a background request to itself (%1$s: %2$s). Queued replies and the benchmark may move slowly; a security plugin or the server firewall may be blocking /wp-json/flx-chat/ requests.' => 'O site não pôde enviar uma solicitação em segundo plano para si mesmo (%1$s:%2$s). As respostas na fila e o benchmark podem se mover lentamente; um plugin de segurança ou o firewall do servidor podem estar bloqueando solicitações /wp-json/flx-chat/.',
  'error' => 'erro',
  'warning' => 'aviso',
  'ok' => 'ok',
  'Your {marka} verification code: {kod}' => 'Seu código de verificação{marka}:{kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'O código é válido por minutos{dk}. Digite-o em seu bate-papo do WhatsApp conosco. Se você não pediu, ignore esta mensagem.',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => 'Algo deu errado; nossa equipe entrará em contato com você o mais breve possível 🌱 Enquanto isso, fique à vontade para perguntar qualquer outra coisa.',
  'Verification attempt failed (%1$d/%2$d): %3$s' => 'Falha na tentativa de verificação (%1$d/%2$d):%3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'A pessoa queria ver seus registros, mas não pôde ser verificada; alguém da equipe deve entrar em contato',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => 'o e-mail não pôde ser enviado (verifique Flux Mail › Configurações de SMTP)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'O assistente enviou um código de verificação para%1$s(%2$s).',
  'code expired' => 'código expirou',
  'wrong code' => 'código errado',
  'The person verified the code for %s; it is added to their record lookups.' => 'A pessoa verificou o código%s; ele é adicionado às pesquisas de registro.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'Os modelos Claude não conseguem ler áudio; escolha um modelo OpenRouter com capacidade de áudio em Configurações › AI › Modelo de mensagem de voz.',
  'The audio could not be transcribed.' => 'Não foi possível transcrever o áudio.',
  'The audio file could not be read.' => 'O arquivo de áudio não pôde ser lido.',
  'Voice message (%1$s) transcribed: %2$s' => 'Mensagem de voz (%1$s) transcrita:%2$s',
  'Voice message (%1$s) could not be processed: %2$s' => 'A mensagem de voz (%1$s) não pôde ser processada:%2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => 'Esta ação não está disponível em uma linha oficial da API do WhatsApp Cloud.',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'Regra 24 horas do WhatsApp: o contato não escreveu nas últimas 24 horas, portanto a API Cloud não enviará mensagem em formato livre; apenas um modelo aprovado pode ser enviado. Tente novamente assim que eles escreverem.',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Uma linha Cloud API precisa do Flux Mail 1.10.0 ou posterior.',
  'The Cloud API cannot send to this address (hidden number or group).' => 'A API Cloud não pode enviar para este endereço (número ou grupo oculto).',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'Não foi possível acessar a conta da Cloud API (İletişim › Conexões).',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Uma linha Cloud API não possui código QR; a conta é configurada em İletişim › Conexões.',
  'The file could not be prepared.' => 'Não foi possível preparar o arquivo.',
  'Flux AI has no image support.' => 'Flux AI não tem suporte de imagem.',
  'The image could not be rendered.' => 'A imagem não pôde ser renderizada.',
  'The assistant\'s image could not be sent: ' => 'Não foi possível enviar a imagem do assistente:',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => 'Olá{first_name}, criamos seu registro de doação:{donation}, total{amount}.{bank}Depois de pagar, você pode enviar o recibo aqui. Obrigado.',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'Olá{first_name}, sua doação foi registrada:{donation}, total{amount}.' . chr(10) . '' . chr(10) . 'Obrigado pelo seu apoio.',
  'The plugin that would run this scenario is inactive.' => 'O plugin que executaria este cenário está inativo.',
  'This user is not allowed to use the staff tools.' => 'Este usuário não tem permissão para usar as ferramentas da equipe.',
  '%1$s linked this chat to staff member %2$s' => '%1$svinculou este chat ao membro da equipe%2$s',
  '%s removed the staff link of this chat' => '%sremoveu o link da equipe deste chat',
  'Chat linked to staff member' => 'Bate-papo vinculado a um membro da equipe',
  'Staff link removed' => 'Link da equipe removido',
  '— Not staff —' => '— Não pessoal —',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'O WhatsApp esconde o número dessa pessoa, então o assistente não consegue reconhecer o pessoal pelo número. Se essa pessoa estiver na sua equipe, vincule-a aqui e o assistente abrirá as ferramentas da equipe.',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => 'O assistente reconhece a equipe pelo número em seu perfil Flux Roles. Se o número não corresponder, você pode vinculá-los aqui; em um chat com um número conhecido, o número vem primeiro.',
  'This channel is not available right now.' => 'Este canal não está disponível no momento.',
  'Site chat' => 'Bate-papo no site',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => 'Todas as mensagens do WhatsApp, chat do site e outros canais aparecem aqui ao vivo. Escolha um bate-papo à esquerda.',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => 'Central de atendimento do WhatsApp (API Evolution): veja mensagens recebidas e enviadas ao vivo, inicie um novo bate-papo, respostas automáticas, tags, tarefas, notas internas, respostas automáticas; Registro de doação (Flux Donate) e certificado (Flux Certificates) no chat, correspondência de recibo. Sugestão de resposta de inteligência artificial e assistente de doação automática com OpenRouter.',
  'Çağrı Merkezi' => 'Central de atendimento',
  'Sohbetler' => 'Bate-papos',
  'AI asistan' => 'Assistente de IA',
  'Çağrı Merkezi Ayarları' => 'Configurações da central de atendimento',
  'Ayarlar' => 'Configurações',
  'Çağrı Merkezi için JavaScript gerekli.' => 'JavaScript é necessário para o Call Center.',
  'Bu sayfaya erişim yetkiniz yok.' => 'Você não tem permissão para acessar esta página.',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => 'Monitore os bate-papos gerenciados pelo assistente, edite suas instruções e documentos e teste as alterações antes de publicá-las.',
  'Asistan ayarları' => 'Configurações do assistente',
  'Bu sayfa için JavaScript gerekli.' => 'Esta página requer JavaScript.',
  'Kapalı' => 'Fechado',
  'Açık, 5 dakika' => 'Ligado, 5 minutos',
  'Açık, 1 saat' => 'Ligado, 1 hora',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'AI precisa do plugin Flux AI & MCP; instale e ative-o e insira a chave em Flux AI & MCP › Configurações.',
  'Yapay zekâ modeli seçilmemiş.' => 'Nenhum modelo de IA selecionado.',
  'Flux AI\'de Anthropic (Claude) anahtarı girilmemiş.' => 'Nenhuma chave Antrópica (Claude) foi inserida no Flux AI.',
  'Flux AI\'de OpenRouter anahtarı girilmemiş.' => 'Nenhuma chave OpenRouter foi inserida no Flux AI.',
  'Model listesi için Flux AI & MCP eklentisi gerekli.' => 'A lista de modelos precisa do plugin Flux AI & MCP.',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'Flux Call Center: recursos de IA (sugestões, assistente, leitura de recibos, mensagens de voz, resumos) precisam do plugin Flux AI & MCP. Instale e ative-o; as chaves salvas no Call Center são movidas para lá automaticamente.',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'Flux Call Center: uma chave%sdiferente já está salva no Flux AI e é a que está em uso. A antiga chave do Call Center não foi movida e não é mais usada.',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'Flux Call Center: as chaves AI foram movidas para Flux AI. A partir de agora, chaves, limites de gastos e registros são gerenciados no Flux AI; as escolhas dos modelos ficam no Call Center.',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'O plugin Flux Donate não está ativo; o assistente retira dele os tipos e preços das doações.',
  'Flux Donate\'ta açık bağış türü yok (Bağış türleri sayfasından bir türü açın).' => 'Não há nenhum tipo de doação aberta no Flux Donate (abra um na página Tipos de doação).',
  'Asistan için seçilen bağış türleri kapalı ya da fiyatsız; açık bir tür seçin ya da seçimi boş bırakın.' => 'As modalidades de doação selecionadas para o assistente são fechadas ou não têm preço; selecione um tipo aberto ou deixe a seleção vazia.',
  'Açık bağış türlerinin hiçbirinde fiyat yok (Flux Donate › Bağış türleri › seçenek fiyatı).' => 'Nenhum dos tipos de doação aberta tem preço (Flux Donate › Tipos de doação › preço da opção).',
