  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => 'Este recibo parece ter sido carregado em nosso sistema antes. O mesmo recibo não poderá ser utilizado para uma segunda doação. Se você fez um pagamento diferente, envie esse recibo; nossa equipe também irá verificar.',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => 'Recebemos seu recibo. O valor nele (%1$s) parece não corresponder ao valor da sua doação (%2$s). Você poderia verificar? Se você fez um pagamento diferente, pode escrever aqui; nossa equipe também dará uma olhada.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Recebemos o seu recibo, mas o destinatário não parece ser a nossa associação. As doações são feitas somente para nossa conta em nome de "%s". Você poderia verificar? Nossa equipe também irá dar uma olhada.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Recebemos seu recibo, mas o destinatário não parece corresponder à nossa conta. Você poderia verificar? Nossa equipe também irá dar uma olhada.',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => 'O arquivo que você enviou não se parece com um recibo de pagamento. Se você pagou, pode enviar o recibo ou uma captura de tela da tela de pagamento aqui.',
