  '+ Yeni rapor' => '+ Novo relatório',
  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => 'O número do destinatário vem de Usuários › Perfil › Número do WhatsApp; permissões de Usuários › Funções e acesso (receber relatórios, visualizar relatório geral, gerenciar relatórios). Os relatórios saem no horário escolhido; sem um agendador de servidor, eles são enviados na próxima visita ao site ou uso do painel de chat.',
