  'Bağlantı bulunamadı. Önce ayarları kaydedin.' => 'Conexão não encontrada. Salve as configurações primeiro.',
  'Mesaj yalnız görsel kodundan oluşuyordu; gönderilmedi.' => 'A mensagem era apenas um código de imagem; não foi enviado.',
  'Bu kişi kara listede; mesaj gönderilmez. Kara listeden çıkarınca yeniden yazabilirsiniz.' => 'Este contato está na lista de bloqueio; nenhuma mensagem é enviada. Remova-os da lista de bloqueio para escrever novamente.',
  'Mesaj kaydedilemedi.' => 'A mensagem não pôde ser salva.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Este contato escreve de um número oculto do WhatsApp (@lid) e a API Evolution (versão%s) não conseguiu enviar para este endereço. Atualize o servidor Evolution API para 2.3 ou posterior; se chegar o número real do contato, o plugin envia para lá.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Este contato escreve de um número oculto do WhatsApp (@lid) e a Evolution API não conseguiu enviar para este endereço. Atualize o servidor Evolution API para 2.3 ou posterior; se chegar o número real do contato, o plugin envia para lá.',
  'WhatsApp bağlantısı yok.' => 'Sem conexão com WhatsApp.',
  'Bağlı ✓' => 'Conectado ✓',
  'Bağlı değil (durum: %s). QR ile bağlayın.' => 'Não conectado (estado:%s). Conecte-se com QR.',
  'Webhook bu siteye ayarlı ✓' => 'Webhook aponta para este site ✓',
  'Evolution API sürümü: %s' => 'Versão da API de evolução:%s',
  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(antigo: respostas a contatos com números ocultos (@lid) podem falhar, atualize para 2.3 ou posterior)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'O webhook não está apontado para este site. Pressione "Configurar webhook".',
  'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.' => 'Configuração do Webhook ✓ As mensagens recebidas agora chegarão aqui.',
  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => 'Importando bate-papos recentes, isso pode demorar um pouco...',
  'Evolution\'da kayıtlı mesaj: %s' => 'Mensagens armazenadas no Evolution:%s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'O Evolution não armazena mensagens, portanto mensagens mais antigas não podem ser carregadas. No servidor Evolution, configure DATABASE_SAVE_DATA_NEW_MESSAGE e DATABASE_SAVE_DATA_HISTORIC como true; para conversas mais antigas, mantenha "Sincronizar histórico completo" ativado nas configurações da instância ao reconectar a linha com QR.',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => 'Bate-papos%1$s, mensagens%2$simportadas ✓',
  'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.' => 'Leia este código via WhatsApp › Dispositivos vinculados › Vincule um dispositivo.',
  'Eşleştirme kodu:' => 'Código de emparelhamento:',
