  'Hata:' => 'Erro:',
  'Bu bağlantı silinsin mi? Sohbet geçmişi silinmez.' => 'Excluir esta conexão? O histórico do bate-papo é mantido.',
  'Yapay zekâya soruluyor…' => 'Perguntando à IA...',
  'Çalışıyor ✓ (%2$s ms): %1$s' => 'Trabalhando ✓ (%2$sms):%1$s',
  'Önce anahtarı ve modeli kaydedin.' => 'Salve a chave e o modelo primeiro.',
  'Bağlantılar' => 'Conexões',
  'Otomatik yanıtlar' => 'Respostas automáticas',
  'Yapay zekâ ve asistan' => 'IA e assistente',
  'Sistem kontrolü' => 'Verificação do sistema',
  'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.' => 'Conecte sua linha do WhatsApp, gerencie respostas automáticas e rótulos.',
  'Sohbetleri aç' => 'Bate-papos abertos',
  'Ayarlar kaydedildi.' => 'Configurações salvas.',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => 'Conexões e configurações que o call center precisa. O status salvo é mostrado; use os botões "teste" em cada guia para uma verificação ao vivo. As mesmas verificações também aparecem com os outros plugins na tela de verificação do sistema do tema.',
  'WhatsApp hatları' => 'Linhas do WhatsApp',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => 'As mensagens são enviadas e recebidas através da API Evolution. As conexões do WhatsApp são gerenciadas no Flux Mail; escolha qual usar aqui. A URL e a chave de API permanecem lá, então você não precisa atualizá-las aqui quando elas mudarem.',
  'İletişim › Bağlantılar' => 'Comunicação › Conexões',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => 'As mensagens são enviadas e recebidas via Evolution API. Se um provedor Evolution estiver configurado em Flux Certificates, você poderá escolher a mesma conexão; o URL e a chave da API permanecem lá.',
