  'Kurulum adımları' => 'Etapas de configuração',
  'Hattı ekleyip kaydedin.' => 'Adicione a linha e salve.',
  '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.' => 'Use "Testar conexão" para ver se o Evolution está acessível. Se a linha não estiver vinculada, escolha “Conectar com QR” e escaneie-a no telefone.',
  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => 'Pressione "Configurar webhook". Mensagens recebidas e mensagens enviadas do telefone e dos Certificados Flux aparecem aqui ao vivo.',
