  'Etiket adı' => 'Nome da etiqueta',
  'Sohbetten kayıt oluşturma' => 'Criando registros de bate-papos',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => 'Os botões no cabeçalho do bate-papo criam um registro de doação (Flux Donate) e um certificado (Flux Certificates), e um recibo recebido é combinado com um registro. Se um plugin não estiver instalado, seu botão ficará oculto.',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => 'Os agentes podem criar registros de doações e combinar recibos',
  'Temsilciler sertifika oluşturup gönderebilsin' => 'Os agentes podem criar e enviar certificados',
  'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster' => 'Mostrar balões de resposta rápida acima da caixa de mensagem',
  'Bağış mesajları' => 'Mensagens de doação',
  'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.' => 'Textos prontos enviados para a pessoa quando um registro é criado (editáveis antes do envio). Se deixado em branco, o texto padrão será usado.',
  'Ödeme bekleniyor (havale sözü)' => 'Aguardando pagamento (transferência prometida)',
  'Bağış alındı' => 'Doação recebida',
  'Dekont onaylandı' => 'Recibo confirmado',
  'Banka bilgisi ({bank})' => 'Dados bancários ({bank})',
  'Alıcı adı, banka, IBAN' => 'Nome do destinatário, banco, IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => 'Se estiver vazio, a conta em WooCommerce › Pagamentos › Transferência bancária será usada.',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variáveis:{first_name},{name},{donation},{amount},{quantity},{bank},{certificate_link},{agent},{brand},{date}.',
  'Yapay zekâ bağlantısı' => 'Conexão de IA',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => 'Chaves, cache de prompt, limites de gastos e registros de uso vêm do plugin Flux AI & MCP; todas as solicitações de IA do Call Center passam por ele. As opções de modelo ficam aqui; se um campo estiver vazio, será utilizado o modelo escolhido para este plugin no Flux AI (ou o padrão).',
  'Flux AI ayarlarını aç' => 'Abra as configurações do Flux AI',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'AI precisa do plugin Flux AI & MCP. Instale e ative-o e, em seguida, insira a chave OpenRouter e/ou Anthropic em Flux AI & MCP › Configurações. Até então sugestões, assistente, leitura de recibos, mensagens de voz e resumos estão desativados.',
  'Yaratıcılık (0–1)' => 'Criatividade (0–1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => 'Valores mais baixos fornecem respostas mais consistentes, valores mais altos, respostas mais livres. 0,4 recomendado.',
  'Model (öneriler için)' => 'Modelo (para sugestões)',
  'Asistan modeli (isteğe bağlı)' => 'Modelo assistente (opcional)',
  'Yukarıdaki model' => 'Modelo acima',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => 'Somente modelos que suportam ferramentas estão listados.',
  'Dekont okuma modeli (isteğe bağlı)' => 'Modelo de leitura de recibo (opcional)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => 'Se o modelo selecionado não conseguir ler imagens, um modelo de visão barato será usado automaticamente.',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => 'Este mês (%1$s): solicitações%2$s, tokens%3$s, cerca de $%4$s.',
  'Cevap önerisi' => 'Sugestões de resposta',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => 'Acima da caixa de mensagem, é sugerida a próxima mensagem da conversa. O agente clica em “Enviar” ou leva para a caixa com “Editar”. Uma sugestão nunca é enviada sozinha.',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => 'Prepare uma sugestão automaticamente quando chegar a última mensagem da pessoa (se estiver desativada, pergunte com o botão ✨)',
  'Kurum bilgisi ve üslup' => 'Informações e tom da organização',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => 'Por exemplo Nossa associação planta mudas em Istambul. O plantio é feito todos os anos entre novembro e março. O certificado é enviado no WhatsApp após a doação. Use um tom caloroso, mas formal.',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => 'Sugestões e o assistente usam isso. Tipos de doações, preços, dados bancários e respostas rápidas são adicionados automaticamente.',
  'Öneri sağlayıcısı' => 'Provedor de sugestões',
  'Bağış asistanı (otomatik cevap)' => 'Assistente de doações (respostas automáticas)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => 'Quando ativado, o assistente responde sozinho: cumprimenta, pergunta o nome para endereçá-los, envia opções de doações e preços, opcionalmente coleta e-mail e “em nome de quem”, e pede confirmação após cada alteração. Após a confirmação abre um registro “aguardando pagamento” no Flux Donate e envia o link da doação, destinatário, IBAN e referência em mensagens separadas. Se o tópico deixar doações, ele passa o chat para a equipe.',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'O plugin Flux Donate não está ativo; o assistente não pode criar registros de doações.',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => 'Instruções, documentos, chats de IA e chat de teste',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => 'Ative o assistente de doações (desmarque para desligá-lo em todos os lugares)',
  'Hangi sohbetlerde cevap versin' => 'A quais bate-papos ele deve responder',
  'Tüm sohbetlerde (önerilen)' => 'Em todos os chats (recomendado)',
  'Temsilciye atanmamış sohbetlerde' => 'Em chats não atribuídos a um agente',
  'Yalnız mesai saatleri dışında' => 'Somente fora do horário de trabalho',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => 'Quando um agente escreve em um chat (do painel ou do telefone), o assistente fica quieto ali pelo tempo abaixo. Use o botão do assistente no cabeçalho do chat para ativá-lo ou desativá-lo por chat.',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => 'Modo teste: responda apenas aos números abaixo',
  'Test numaraları' => 'Números de teste',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => 'Separe com vírgulas ou novas linhas. Não usado quando o modo de teste está desativado.',
  'Temsilci yazınca susma (saat)' => 'Silêncio depois que um agente escreve (horas)',
  'Fiyat listesindeki adetler' => 'Quantidades na tabela de preços',
  'Konuşma geçmişi (saat)' => 'Histórico de conversas (horas)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => 'Antes de responder, o assistente lê todas as mensagens deste período.',
  'Asistanın sunduğu bağış türleri' => 'Tipos de doação que o assistente oferece',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => 'Se nenhum for selecionado, todos os tipos abertos serão oferecidos. Quando um novo tipo é aberto no Flux Donate, o assistente também sabe disso.',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => 'Pré-verificação de recebimento: quando o contato envia um recibo, a IA compara o valor, destinatário e IBAN com a doação, informa o resultado ao contato, anexa o arquivo ao registro da doação e entrega o chat para a equipe para aprovação final (não marca como pago)',
  'Fiyat listesinin son satırı' => 'Última linha da lista de preços',
  'Ödeme bilgileri' => 'Detalhes de pagamento',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => 'Se o destinatário e o IBAN estiverem vazios, serão usados aqueles em WooCommerce › Pagamentos › Transferência bancária (a conta mostrada nos pedidos). Preencha-os apenas se o assistente usar uma conta diferente.',
  'Alıcı adı' => 'Nome do destinatário',
  'Havale açıklaması' => 'Descrição da transferência',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => 'Variáveis:{type},{name},{amount},{quantity}',
  'Bağış sayfası adresi' => 'URL da página de doação',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => 'O tipo e a quantidade selecionados são adicionados ao link (?flxb_opt=...&flxb_qty=...).',
  'Ödeme bilgilerinden sonraki mesaj' => 'Mensagem após os detalhes do pagamento',
  'Bağış iptali onay sorusu' => 'Pergunta sobre cancelamento de doação',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => 'O assistente cancela apenas as doações não pagas, com a confirmação da pessoa. Vazio = texto padrão. Variáveis:{bagis},{tutar}.',
  'Günlük sınır dolunca gönderilen mesaj' => 'Mensagem enviada quando o limite diário é atingido',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => 'Enviado uma vez quando um chat atinge o limite de respostas do dia; o chat é entregue à equipe. Redefina-o no menu ⋮ › Uso do assistente do bate-papo.',
  'Ekibe devrederken gönderilen mesaj' => 'Mensagem enviada ao entregar para a equipe',
  'Asistan cevap veremezse giden mesaj' => 'Mensagem enviada quando o assistente não consegue atender',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => 'Caso a IA falhe, o tempo limite seja atingido ou a fila fique muito longa, essa mensagem é enviada e o chat é repassado para a equipe; a pessoa nunca fica sem resposta.',
  'Bekleme mesajından önce en az (sn)' => 'Espera mínima antes da(s) mensagem(s) de retenção',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => 'A mensagem em espera não é enviada até alguns segundos após a mensagem da pessoa; enquanto isso, o assistente tenta novamente.',
  'Bir cevabın en uzun süresi (sn)' => 'Maior tempo para uma(s) resposta(s)',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'A Hostinger pode cortar solicitações em aproximadamente 60 segundos; 50 é recomendado.',
  'Devirde bildirim gidecek numaralar' => 'Números notificados na transferência',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => 'Quando o assistente entrega um chat para a equipe, uma mensagem de WhatsApp é enviada para esses números da mesma linha: nome do contato, telefone, motivo, últimas mensagens e link do painel. Separe com vírgulas ou novas linhas. O assistente não fala com esses números.',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => 'Quando o contato escreve uma dessas, o assistente envia imediatamente a mensagem de hand-off acima e desliga naquele chat. Se deixado em branco, a lista de exemplos será usada.',
  'Asistana ek talimatlar' => 'Instruções extras para o assistente',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => 'Por exemplo As mudas são plantadas em Kocaeli. Os certificados são enviados assim que a doação for confirmada.',
  'Kişi mesaj istemeyince gönderilen son mesaj' => 'Última mensagem quando um contato desativa',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => 'Se alguém escrever algo como “não me mande uma mensagem”, o assistente enviará essa mensagem e a colocará na lista de bloqueio. Uma pessoa na lista de bloqueio não recebe WhatsApp, e-mail ou SMS; gerencie a lista em Bate-papos › ☰ › Lista de bloqueio.',
  'Kişi hafızası ve arka plan işleri' => 'Memória de contato e trabalhos em segundo plano',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => 'Memória de contato: o assistente lembra detalhes duradouros (forma de endereço, nomes de parentes, números, preferências); bate-papos expirados são resumidos',
  'Sohbet kaç saat sessiz kalınca özetlensin' => 'Resuma um bate-papo depois que ele estiver silencioso por (horas)',
  'Aynı anda en fazla iş' => 'Máximo de trabalhos ao mesmo tempo',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => 'Quantas pessoas podem ser atendidas ao mesmo tempo. As respostas do assistente sempre vêm em primeiro lugar; os resumos não começam enquanto alguém está sendo atendido ou esperando. Cada trabalho usa um trabalhador PHP: em hospedagem compartilhada, fique abaixo da metade do limite total de trabalhadores dos seus sites (por exemplo, 20-30 de 60 trabalhadores).',
  'Yalnız cevaplara ayrılan işçi' => 'Trabalhadores reservados para respostas',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => 'Muitos trabalhadores nunca aceitam resumos ou lembretes.',
  'Özet saatleri' => 'Horário de resumo',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => 'Os resumos são executados apenas entre esses horários (exceto um manual "Resumir agora"). Se ambos forem iguais, a qualquer momento.',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => 'Quando alguém envia uma mensagem de voz, o assistente transforma em texto e responde (o texto também aparece no painel como uma linha do sistema)',
  'En uzun ses (sn)' => 'Mensagem de voz mais longa (seg)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => 'Para mensagens mais longas, o assistente diz “a mensagem de voz era muito longa para ouvirmos”.',
  'Sesli mesaj modeli (isteğe bağlı)' => 'Modelo de mensagem de voz (opcional)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => 'Modelo de áudio barato (Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => 'Deve ser um modelo OpenRouter que aceite áudio (Claude não). É necessária uma chave OpenRouter.',
  'Görseller' => 'Imagens',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => 'Deixe o assistente desenhar uma imagem quando for útil (tabela, relatório, diagrama); vai para o WhatsApp como imagem, o texto é enviado separadamente',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => 'O renderizador de imagem Flux AI é usado (Flux AI & MCP › Configurações › Imagens).',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => 'Nenhum renderizador de imagem no servidor: insira um endereço Gotenberg em Flux AI & MCP › Configurações › Imagens ou instale o Imagick (SVG). Até então o assistente não desenha imagens.',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => 'Funciona quando o Flux AI 0.2.0 ou posterior estiver instalado.',
  'Başkası adına bağış' => 'Doação em nome de alguém',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => 'Caso a doação esteja em nome de outra pessoa e tenha sido informado o número dela (cartão de contato ou número digitado), envie também o certificado para esse número no WhatsApp assim que o pagamento for aprovado',
  'Sertifikadan önce giden mesaj' => 'Mensagem enviada antes do certificado',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => 'Em seguida, a mensagem do certificado WhatsApp da Flux Certificates é enviada. Variáveis:{ad},{bagisci},{bagis},{brand}.',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => 'Caso uma pessoa pergunte, o assistente configura um lembrete (por exemplo, “lembre-me do plantio de mudas todo mês”, “envie-me seus projetos mais recentes todo mês”, “peça-me uma muda todo mês”); na hora certa, o assistente escreve e envia a mensagem',
  'Saat söylenmezse' => 'Quando nenhum tempo é dado',
  'Kişi başına en fazla' => 'No máximo por pessoa',
  'Personel (Flux Roles)' => 'Equipe (funções de fluxo)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => 'Funciona assim que o Flux Roles 1.1.0 estiver instalado: usuários cujo número está definido em Perfil › Número do WhatsApp obtêm ferramentas assistentes extras com base em suas permissões.',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => 'Conceder ferramentas auxiliares extras aos números da equipe com permissão (doação em nome de alguém com link de pagamento, meus doadores, relatório geral)',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => 'Notificar a equipe no WhatsApp quando uma doação indicada for paga ou cancelada',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => 'Primeira mensagem ao doador para uma doação aberta pela equipe',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => 'Olá{ad}🌱 Sua solicitação de doação{bagis}via{personel}foi recebida. Você pode pagar com os detalhes abaixo.',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Segue link de pagamento e dados bancários. Variáveis:{ad},{adsoyad},{personel},{bagis}.',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => 'Quando uma doação indicada por um funcionário for paga e seus certificados forem feitos, envie-os também para o funcionário no WhatsApp (assim como o doador)',
  'Personele sertifikadan önce giden mesaj' => 'Mensagem enviada ao funcionário antes do certificado',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variáveis:{ad},{bagisci},{bagis},{no},{brand}.',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => 'Quantas vezes a equipe pode reenviar um certificado de doação',
