  'Tahmin ücret limitini aşıyor; limit dolunca çalıştırma durur.' => 'A estimativa excede o limite de custo; a execução para quando o limite é atingido.',
  'Yeni çalıştırma' => 'Nova corrida',
  'Senaryolar test sohbetindeki gibi oynatılır: WhatsApp\'a mesaj gitmez, kayıt açılmaz. Model gerçekten çağrılır; ücret yapay zekâ hesabınızdan (OpenRouter ya da Anthropic) düşer ve limit dolunca çalıştırma durur.' => 'Os cenários são reproduzidos como no chat de teste: nenhuma mensagem do WhatsApp é enviada e nenhum registro é criado. O modelo é realmente chamado; o custo é cobrado em sua conta AI (OpenRouter ou Anthropic) e a corrida é interrompida quando o limite é atingido.',
