  'Hâlâ Flux Certificates\'daki eski sağlayıcı kullanılıyor; bağlantıyı Flux Mail\'e taşıyıp burada seçin.' => 'Ainda utilizando o antigo provedor em Certificados Flux; mova a conexão para Flux Mail e selecione-a aqui.',
