  '%s: webhook (gelen mesajlar)' => '%s: webhook (mensagens recebidas)',
  'Evolution\'dan hiç olay gelmedi; gelen mesajlar panele düşmez. "Webhook\'u kur" düğmesine basın.' => 'Nenhum evento chegou da Evolution; as mensagens recebidas não serão exibidas no painel. Pressione "Configurar webhook".',
  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => 'O último evento chegou%s. A linha pode estar silenciosa; envie uma mensagem para si mesmo ou configure o webhook novamente para ter certeza.',
  'Son olay %s geldi.' => 'O último evento chegou%s.',
  'Flux Mail entegrasyonu' => 'Integração Flux Mail',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => 'Ativo: as conexões do WhatsApp são obtidas em Comunicação › Conexões.',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux Mail não está ativo; as conexões são obtidas dos Certificados Flux ou deste plugin.',
  'Flux Certificates entegrasyonu' => 'Integração de certificados Flux',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => 'Ativo: certificados podem ser criados e enviados a partir de chats.',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'Os Certificados Flux não estão ativos; as ações de certificado em bate-papos estão desativadas.',
  'Flux Donate entegrasyonu' => 'Integração Flux Donate',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => 'Ativo: registros de doações, correspondência de recibos e assistente estão disponíveis nos chats.',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => 'Flux Donate não está ativo; registros de doações, correspondência de recibos e assistente de doações estão desativados.',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'O plugin Flux AI & MCP não está instalado; Os recursos de IA (sugestões, assistente, leitura de recibos, mensagens de voz, resumos) estão desativados. Instale o Flux AI e insira a chave lá.',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'Nenhuma chave foi inserida no Flux AI; sugestões de mensagens e o assistente estão desligados.',
  'Anahtar var ama model seçilmemiş.' => 'Chave salva, mas nenhum modelo selecionado.',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => 'Nenhuma chave de provedor foi inserida no Flux AI para o modelo selecionado (%s).',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => 'Chave salva, modelo:%s. Use "Conexão de teste" para uma verificação ao vivo.',
