  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%snão oferece suporte a ferramentas; escolha um modelo compatível com ferramentas para o assistente.',
  'Dekont okuma modeli' => 'Modelo de leitura de recibo',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => '%snão consegue ler imagens; a pré-verificação do recibo não funcionará. Escolha um modelo de leitura de recibos com capacidade de imagem.',
  'Asistanın ödeme bilgileri' => 'Detalhes de pagamento do assistente',
  'Alıcı adı ve IBAN tanımlı.' => 'Nome do destinatário e conjunto de IBAN.',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => 'Nome do destinatário ou IBAN ausente; os dados bancários não podem ser enviados após a confirmação.',
  'Bağış sayfası linki' => 'Link da página de doações',
  'Bağış sayfası bulunamadı; asistan link göndermez.' => 'Página de doação não encontrada; o assistente não enviará um link.',
  'Arka plan istekleri' => 'Solicitações em segundo plano',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => 'O site não pôde enviar uma solicitação em segundo plano para si mesmo (%1$s:%2$s). As respostas na fila e o benchmark podem se mover lentamente; um plugin de segurança ou o firewall do servidor podem estar bloqueando solicitações /wp-json/flx-chat/.',
