  '{marka} doğrulama kodunuz: {kod}' => 'Seu código de verificação{marka}:{kod}',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => 'O código é válido por minutos{dk}. Digite-o em seu bate-papo do WhatsApp conosco. Se você não pediu, ignore esta mensagem.',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => 'Algo deu errado; nossa equipe entrará em contato com você o mais breve possível 🌱 Enquanto isso, fique à vontade para perguntar qualquer outra coisa.',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => 'Falha na tentativa de verificação (%1$d/%2$d):%3$s',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => 'A pessoa queria ver seus registros, mas não pôde ser verificada; alguém da equipe deve entrar em contato',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => 'o e-mail não pôde ser enviado (verifique Flux Mail › Configurações de SMTP)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => 'O assistente enviou um código de verificação para%1$s(%2$s).',
  'kodun süresi doldu' => 'código expirou',
  'yanlış kod' => 'código errado',
  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => 'A pessoa verificou o código%s; ele é adicionado às pesquisas de registro.',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => 'Os modelos Claude não conseguem ler áudio; escolha um modelo OpenRouter com capacidade de áudio em Configurações › AI › Modelo de mensagem de voz.',
  'Ses metne çevrilemedi.' => 'Não foi possível transcrever o áudio.',
  'Ses dosyası okunamadı.' => 'O arquivo de áudio não pôde ser lido.',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => 'Mensagem de voz (%1$s) transcrita:%2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => 'A mensagem de voz (%1$s) não pôde ser processada:%2$s',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => 'Esta ação não está disponível em uma linha oficial da API do WhatsApp Cloud.',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'Regra 24 horas do WhatsApp: o contato não escreveu nas últimas 24 horas, portanto a API Cloud não enviará mensagem em formato livre; apenas um modelo aprovado pode ser enviado. Tente novamente assim que eles escreverem.',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'Uma linha Cloud API precisa do Flux Mail 1.10.0 ou posterior.',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'A API Cloud não pode enviar para este endereço (número ou grupo oculto).',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => 'Não foi possível acessar a conta da Cloud API (İletişim › Conexões).',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'Uma linha Cloud API não possui código QR; a conta é configurada em İletişim › Conexões.',
  'Dosya hazırlanamadı.' => 'Não foi possível preparar o arquivo.',
  'Flux AI görsel desteği yok.' => 'Flux AI não tem suporte de imagem.',
  'Görsel çevrilemedi.' => 'A imagem não pôde ser renderizada.',
  'Asistanın görseli gönderilemedi: ' => 'Não foi possível enviar a imagem do assistente:',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => 'Olá{first_name}, criamos seu registro de doação:{donation}, total{amount}.{bank}Depois de pagar, você pode enviar o recibo aqui. Obrigado.',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => 'Olá{first_name}, sua doação foi registrada:{donation}, total{amount}.' . chr(10) . '' . chr(10) . 'Obrigado pelo seu apoio.',
  'Bu senaryoyu oynatacak eklenti kapalı.' => 'O plugin que executaria este cenário está inativo.',
  'Bu kullanıcının personel araçları yetkisi yok.' => 'Este usuário não tem permissão para usar as ferramentas da equipe.',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => '%1$svinculou este chat ao membro da equipe%2$s',
  '%s sohbetin personel bağlantısını kaldırdı' => '%sremoveu o link da equipe deste chat',
  'Sohbet personele bağlandı' => 'Bate-papo vinculado a um membro da equipe',
  'Personel bağlantısı kaldırıldı' => 'Link da equipe removido',
  '— Personel değil —' => '— Não pessoal —',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'O WhatsApp esconde o número dessa pessoa, então o assistente não consegue reconhecer o pessoal pelo número. Se essa pessoa estiver na sua equipe, vincule-a aqui e o assistente abrirá as ferramentas da equipe.',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => 'O assistente reconhece a equipe pelo número em seu perfil Flux Roles. Se o número não corresponder, você pode vinculá-los aqui; em um chat com um número conhecido, o número vem primeiro.',
  'Bu kanal şu an kullanılamıyor.' => 'Este canal não está disponível no momento.',
  'Site sohbeti' => 'Bate-papo no site',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => 'Todas as mensagens do WhatsApp, chat do site e outros canais aparecem aqui ao vivo. Escolha um bate-papo à esquerda.',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => 'Central de atendimento do WhatsApp (API Evolution): veja mensagens recebidas e enviadas ao vivo, inicie um novo bate-papo, respostas automáticas, tags, tarefas, notas internas, respostas automáticas; Registro de doação (Flux Donate) e certificado (Flux Certificates) no chat, correspondência de recibo. Sugestão de resposta de inteligência artificial e assistente de doação automática com OpenRouter.',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => 'Central de atendimento do WhatsApp (API Evolution): veja mensagens recebidas e enviadas ao vivo, inicie um novo bate-papo, respostas automáticas, tags, tarefas, notas internas, respostas automáticas; Registro de doação (Flux Donate) e certificado (Flux Certificates) no chat, correspondência de recibo. Sugestão de resposta de inteligência artificial e assistente de doação automática com OpenRouter.',
'Hide'=>'Ocultar',
'Show'=>'Mostrar',
'Deleted for everyone'=>'Apagada para todos',
'Hidden in the panel'=>'Oculta no painel',
'Delete for everyone'=>'Apagar para todos',
'Hide in the panel only'=>'Ocultar apenas no painel',
'WhatsApp doesn\'t allow deleting a received message for everyone; it stays on the contact\'s phone and is only hidden in the panel.'=>'O WhatsApp não permite apagar para todos uma mensagem recebida; ela fica no telefone do contato e é apenas ocultada no painel.',
'Delete for everyone is turned off in the settings; the message is only hidden in the panel and stays on the contact\'s phone.'=>'Apagar para todos está desativado nas configurações; a mensagem é apenas ocultada no painel e fica no telefone do contato.',
'This channel doesn\'t support delete for everyone; the message is only hidden in the panel and stays on the contact\'s phone.'=>'Este canal não permite apagar para todos; a mensagem é apenas ocultada no painel e fica no telefone do contato.',
'The time limit for delete for everyone has passed (WhatsApp allows about {h} hours after sending). The message stays on the contact\'s phone and is only hidden in the panel.'=>'O prazo para apagar para todos terminou (o WhatsApp permite cerca de {h} horas após o envio). A mensagem fica no telefone do contato e é apenas ocultada no painel.',
'Only the sender or an administrator can delete this message for everyone; you can hide it in the panel.'=>'Só o remetente ou um administrador pode apagar esta mensagem para todos; você pode ocultá-la no painel.',
'If deleted for everyone, the message also turns into "This message was deleted" on the contact\'s phone. Time left: about {n} hours.'=>'Se apagar para todos, a mensagem também vira "Esta mensagem foi apagada" no telefone do contato. Tempo restante: cerca de {n} horas.',
'Deleted messages are kept on the server: the chat shows a "This message was deleted" line and the team can click it to see the content. AI does not read deleted messages.'=>'Mensagens apagadas ficam guardadas no servidor: a conversa mostra "Esta mensagem foi apagada" e a equipe pode clicar para ver o conteúdo. A IA não lê mensagens apagadas.',
'Message not found.'=>'Mensagem não encontrada.',
'This message was already deleted.'=>'Esta mensagem já foi apagada.',
'Only the sender or an administrator can delete this message for everyone.'=>'Só o remetente ou um administrador pode apagar esta mensagem para todos.',
'This message can\'t be deleted for everyone on this channel. You can hide it in the panel instead.'=>'Esta mensagem não pode ser apagada para todos neste canal. Você pode ocultá-la no painel.',
'The time limit for deleting for everyone has passed. You can hide it in the panel instead.'=>'O prazo para apagar para todos terminou. Você pode ocultá-la no painel.',
'WhatsApp did not delete the message.'=>'O WhatsApp não apagou a mensagem.',
'Delete for everyone time limit (hours)'=>'Prazo para apagar para todos (horas)',
'WhatsApp lets you delete a sent message for everyone only for about 2 days and 12 hours (60 hours). After this limit, or for received messages, the message is only hidden in the panel: it stays on the contact\'s phone. 0 turns off delete for everyone. Deleted messages are never removed from the server; the team can still open them.'=>'O WhatsApp só permite apagar para todos uma mensagem enviada por cerca de 2 dias e 12 horas (60 horas). Depois disso, ou em mensagens recebidas, a mensagem é apenas ocultada no painel e fica no telefone do contato. 0 desativa apagar para todos. Mensagens apagadas nunca são removidas do servidor; a equipe ainda pode abri-las.',
),
);
